<?php
namespace App\Services;
use App\Models\HomeRemedy;
class HomeRemedyExportService { public static function columns():array{return ['id','title_en','title_hi','slug','problem_name_en','problem_name_hi','short_description_en','short_description_hi','description_en','description_hi','ingredients_en','ingredients_hi','preparation_en','preparation_hi','steps_en','steps_hi','usage_instructions_en','usage_instructions_hi','dosage_or_quantity_en','dosage_or_quantity_hi','frequency_en','frequency_hi','recommended_duration_en','recommended_duration_hi','traditional_benefit_en','traditional_benefit_hi','how_it_may_help_en','how_it_may_help_hi','evidence_summary_en','evidence_summary_hi','evidence_level','suitable_for_en','suitable_for_hi','not_suitable_for_en','not_suitable_for_hi','child_warning_en','child_warning_hi','pregnancy_warning_en','pregnancy_warning_hi','elderly_warning_en','elderly_warning_hi','medical_condition_warning_en','medical_condition_warning_hi','medicine_interactions_en','medicine_interactions_hi','possible_side_effects_en','possible_side_effects_hi','red_flags_en','red_flags_hi','when_to_see_doctor_en','when_to_see_doctor_hi','category','ingredients','doctor_speciality','search_keywords_en','search_keywords_hi','search_aliases','meta_title_en','meta_title_hi','meta_description_en','meta_description_hi','references','source_notes','is_featured','is_published','medical_review_status','sort_order'];} public function rows($query){$cols=self::columns();$rows=[$cols];foreach($query->with(['category','ingredients','speciality'])->cursor() as $r){$row=[];foreach($cols as $c){$row[]=match($c){'category'=>$r->category?->name_en,'ingredients'=>$r->ingredients->pluck('name_en')->implode('|'),'doctor_speciality'=>$r->speciality?->name_en,default=>$r->{$c}??''};}$rows[]=$row;}return $rows;} public function csv($query){$h='php://temp';foreach($this->rows($query) as $row)fputcsv($h,$row);rewind($h);return stream_get_contents($h);}}
